import AjvModule from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

interface SchemaCompiler {
  compile(schema: Record<string, unknown>): ValidateFunction;
}

type AjvConstructor = new (options?: Record<string, unknown>) => SchemaCompiler;

// The default export is the constructable compiler in every ajv major; the cast spans their differing type shapes.
const Ajv = AjvModule as unknown as AjvConstructor;

const inputSchemaCompiler = new Ajv({strict: false, validateFormats: false, allErrors: true});

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface SchemaViolation {
  instancePath?: string;
  dataPath?: string;
  message?: string;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validateInput: ValidateFunction;
  validatorsBySchema?: WeakMap<object, ValidateFunction>;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validateInput = compileInputSchema(resolved.name, resolved.inputSchema);
    const stored: StoredTool = {definitionSource: definition, execute, validateInput};
    if (typeof definition === 'function') {
      stored.validatorsBySchema = new WeakMap([[resolved.inputSchema, validateInput]]);
    }
    this.tools.set(resolved.name, stored);
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the registered inputSchema and returns a rejection ToolResponse on failure; throws only for an unknown tool name (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validateInput = this.validatorFor(tool);
    if (!validateInput(input)) {
      const violations = describeViolations(validateInput.errors ?? []);
      log.warn('tool', 'input rejected by schema', {name, violations});
      return {result: `Invalid input for tool '${name}': ${violations}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (typeof tool.definitionSource !== 'function') {
      return tool.validateInput;
    }
    const definition = tool.definitionSource();
    const validators = tool.validatorsBySchema;
    if (!validators) {
      return compileInputSchema(definition.name, definition.inputSchema);
    }
    let compiled = validators.get(definition.inputSchema);
    if (!compiled) {
      compiled = compileInputSchema(definition.name, definition.inputSchema);
      validators.set(definition.inputSchema, compiled);
    }
    return compiled;
  }
}

function compileInputSchema(toolName: string, inputSchema: ToolDefinition['inputSchema']): ValidateFunction {
  try {
    return inputSchemaCompiler.compile(inputSchema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Tool '${toolName}' has an invalid inputSchema: ${reason}`, {cause: error});
  }
}

function describeViolations(errors: SchemaViolation[]): string {
  return errors.map(error => describeViolation(error)).join('; ');
}

function describeViolation(error: SchemaViolation): string {
  const reason = error.message ?? 'input did not match the declared schema';
  const path = violationPath(error);
  return path ? `${path} ${reason}` : reason;
}

function violationPath(error: SchemaViolation): string {
  const rawPath = error.instancePath ?? error.dataPath ?? '';
  const withoutLeading = rawPath.replace(/^[./]+/, '');
  return withoutLeading.replace(/[./]+/g, '.');
}

