  /** Validates input against the registered inputSchema and returns a rejection ToolResponse on failure; throws only for an unknown tool name (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    if (!tool.validateInput(input)) {
      const violations = describeViolations(tool.validateInput.errors ?? []);
      log.warn('tool', 'input rejected by schema', {name, violations});
      return {result: `Invalid input for tool '${name}': ${violations}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function compileInputSchema(toolName: string, inputSchema: ToolDefinition['inputSchema']): ValidateFunction {
  try {
    return inputSchemaCompiler.compile(inputSchema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Tool '${toolName}' has an invalid inputSchema: ${reason}`);
  }
}

function describeViolations(errors: ErrorObject[]): string {
  return errors
    .map(error => {
      const path = error.instancePath.replace(/^\//, '').replace(/\//g, '.');
      return path ? `${path} ${error.message}` : error.message;
    })
    .join('; ');
}

