import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('reports a missing required location and does not run the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'local_forecast',
        description: 'Forecasts weather for the requested location and country',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, country: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'clear';
      }
    );

    const response = await registry.execute('local_forecast', {});

    expect({
      executorCalls,
      namesRequiredLocation: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      namesRequiredLocation: true,
    });
  });

  it('passes valid input through to the executor unchanged, exactly once, including undeclared properties', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'city_lookup',
        description: 'Looks up a city and may receive undeclared extra fields',
        inputSchema: {
          type: 'object',
          properties: {city: {type: 'string'}},
          required: ['city'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'found';
      }
    );

    const input = {city: 'Lyon', region: 'Auvergne'};
    await registry.execute('city_lookup', input);

    expect(receivedInputs).toEqual([{city: 'Lyon', region: 'Auvergne'}]);
  });

  it('throws Unknown tool for a name that was never registered', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('never_registered', {})).rejects.toThrow('Unknown tool: never_registered');
  });

  it('compiles a static schema once at register time and reuses it across ten execute calls', async () => {
    let schemaReads = 0;
    const schema = new Proxy(
      {type: 'object', properties: {query: {type: 'string'}}, required: ['query']},
      {
        get(target: Record<string, unknown>, property: string | symbol) {
          schemaReads += 1;
          return target[property];
        },
      }
    );
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'search_records',
        description: 'Searches stored records matching a query',
        inputSchema: schema,
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );
    const readsAtRegister = schemaReads;

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('search_records', {query: `term-${String(call)}`});
    }

    expect({executorCalls, schemaReadsAcrossCalls: schemaReads - readsAtRegister}).toEqual({
      executorCalls: 10,
      schemaReadsAcrossCalls: 0,
    });
  });

  it('validates a function-valued source against the schema current at that call, not a stale cached one', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let sourceCalls = 0;
    registry.register(
      () => {
        sourceCalls += 1;
        return {
          name: 'dynamic_lookup',
          description: 'Requires region once it has been resolved twice',
          inputSchema:
            sourceCalls === 1
              ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
              : {type: 'object', properties: {region: {type: 'string'}}, required: ['region']},
        };
      },
      async () => {
        executorCalls += 1;
        return 'done';
      }
    );

    const first = await registry.execute('dynamic_lookup', {location: 'Nice'});
    const second = await registry.execute('dynamic_lookup', {location: 'Nice'});

    expect({
      executorCalls,
      firstResult: first.result,
      secondNamesCurrentRequiredField: second.result.includes('region') && /required/i.test(second.result),
    }).toEqual({
      executorCalls: 1,
      firstResult: 'done',
      secondNamesCurrentRequiredField: true,
    });
  });

  it('reuses the compiled validator when a function-valued source returns the same schema object', async () => {
    let schemaReads = 0;
    const schema = new Proxy(
      {type: 'object', properties: {topic: {type: 'string'}}, required: ['topic']},
      {
        get(target: Record<string, unknown>, property: string | symbol) {
          schemaReads += 1;
          return target[property];
        },
      }
    );
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'tag_search',
        description: 'Searches entries tagged with a topic',
        inputSchema: schema,
      }),
      async () => 'tagged'
    );

    await registry.execute('tag_search', {topic: 'charts'});
    const readsAfterFirstCall = schemaReads;

    await registry.execute('tag_search', {topic: 'maps'});

    expect(schemaReads - readsAfterFirstCall).toBe(0);
  });
});

